import { useEffect, useState } from "react";
import { FiActivity, FiCopy, FiLink, FiRefreshCw } from "react-icons/fi";
import { rpc_urls } from "../contract/config";
import { getWalletDiagnostic } from "../utils/walletDiagnostics";
import { getWalletErrorMessage } from "../utils/walletErrors";

export default function WalletRecovery({ cont, error }) {
    const [busy, setBusy] = useState(false);
    const [message, setMessage] = useState("");
    const [lastError, setLastError] = useState(error);
    const [rpcUrl, setRpcUrl] = useState(rpc_urls[0]);
    const [foundHash, setFoundHash] = useState("");
    const [released, setReleased] = useState(false);
    const [activeAction, setActiveAction] = useState("");
    useEffect(() => { setLastError(error); setMessage(""); setFoundHash(""); setReleased(false); }, [error]);
    if (!error) return null;
    const diagnostic = getWalletDiagnostic(lastError);
    const recoveryId = error?.recoveryId;
    const run = async (action) => {
        if (busy) return;
        if (action === "retry" && !window.confirm("MetaMask の履歴とクイズ一覧を確認し、保留中の取引・確認待ち画面がないことを確認しましたか？ 元の取引が遅れて送信されると重複する可能性があります。この操作自体では取引を送信せず、再試行を許可するだけです。")) return;
        setBusy(true);
        setActiveAction(action);
        setMessage("");
        try {
            if (action === "result") {
                const result = await cont.recheck_quiz_transaction(recoveryId);
                setFoundHash(result.hash);
                setMessage("送信済みの取引を見つけました。元の作成・回答ボタンを押すと、この取引の結果確認から再開します。新しい取引は送信しません。");
            } else if (action === "retry") {
                await cont.allow_quiz_transaction_retry(recoveryId);
                setReleased(true);
                setMessage("再試行を許可しました。入力内容を確認して、元の作成・回答ボタンから再試行してください。まだ取引は送信していません。");
            } else if (action === "permissions") {
                await cont.reconnect_wallet_permissions();
                setMessage("接続権限を設定し直しました。登録済みのアカウントを確認し、必要な操作を再度行ってください。取引は送信していません。");
            } else {
                const result = action === "repair" ? await cont.repair_wallet_network() : await cont.check_wallet_network();
                if (result.rpcUrl) setRpcUrl(result.rpcUrl);
                setMessage("Polygon Amoy（80002）との通信を確認できました。MetaMask の取引履歴を確認してから、必要な操作を再度行ってください。取引は送信していません。");
            }
            setLastError(null);
        } catch (failure) {
            if (rpc_urls.includes(failure?.rpcUrl)) setRpcUrl(failure.rpcUrl);
            setLastError(failure);
            setMessage(getWalletErrorMessage(failure) || "操作を完了できません。MetaMask のネットワーク設定を確認してください。接続権限を設定し直せない場合は、MetaMask の接続済みサイトからこのサイトを切断し、再接続してください。");
        } finally { setBusy(false); setActiveAction(""); }
    };
    const copy = async () => {
        const text = JSON.stringify({ network: "Polygon Amoy", chainId: 80002, ...diagnostic }, null, 2);
        try {
            const copied = await cont.copyTextToClipboard?.(text);
            setMessage(copied ? "診断内容をコピーしました。問題の本文・正解や秘密鍵は含めていません。" : "コピーできませんでした。下のエラー詳細を確認してください。");
        } catch (_) { setMessage("コピーできませんでした。下のエラー詳細を確認してください。"); }
    };
    return <section aria-label="ウォレット接続の診断" style={{ padding: "16px 0", borderTop: "1px solid var(--border-color, #555)", borderBottom: "1px solid var(--border-color, #555)", marginBottom: 20, overflowWrap: "anywhere" }}>
        <h3 className="heading-md">ウォレット接続の診断</h3>
        {lastError && <p style={{ fontSize: 13, whiteSpace: "pre-wrap", overflowWrap: "anywhere" }}>発生箇所: {diagnostic.stage || "不明"}{diagnostic.codes.length ? ` / コード: ${diagnostic.codes.join(", ")}` : ""}<br />{diagnostic.reason || "エラー詳細を取得できませんでした。"}</p>}
        <div style={{ display: "flex", flexWrap: "wrap", gap: 10, margin: "12px 0" }}>
            {recoveryId && <button type="button" className="btn-ghost" disabled={busy || released} onClick={() => run("result")}><FiActivity aria-hidden="true" /> 送信結果を再確認</button>}
            {recoveryId && <button type="button" className="btn-ghost" disabled={busy || released || Boolean(foundHash)} onClick={() => run("retry")}><FiRefreshCw aria-hidden="true" /> 未送信を確認して再試行を許可</button>}
            <button type="button" className="btn-ghost" disabled={busy} onClick={() => run("check")}><FiActivity aria-hidden="true" /> 通信を確認</button>
            <button type="button" className="btn-ghost" disabled={busy} onClick={() => run("repair")}><FiRefreshCw aria-hidden="true" /> RPC設定を修復</button>
            <button type="button" className="btn-ghost" disabled={busy} onClick={() => run("permissions")}><FiLink aria-hidden="true" /> 接続権限を再設定</button>
            <button type="button" className="btn-ghost" aria-label="診断内容をコピー" title="診断内容をコピー" disabled={busy} onClick={copy}><FiCopy aria-hidden="true" /></button>
        </div>
        {busy && <p role="status">{["result", "retry", "check"].includes(activeAction) ? "チェーン上の状態を確認しています。" : "MetaMask の確認画面を確認してください。"}取引の送信は行いません。</p>}
        {message && <p role="status">{message}</p>}
        {foundHash && <p><a href={`https://amoy.polygonscan.com/tx/${foundHash}`} target="_blank" rel="noopener noreferrer">見つかった取引を確認</a></p>}
        <details>
            <summary>手動のRPC設定・直前のエラー詳細</summary>
            <p>RPC設定が変わらない場合は、MetaMask の Polygon Amoy 設定で次のURLを追加し、既定のRPCに選んでください。チェーンIDは 80002 です。</p>
            <p><code style={{ overflowWrap: "anywhere" }}>{rpcUrl}</code></p>
            <p>接続権限の再設定は、このサイトへの接続だけを切断して再接続します。ウォレットの削除・初期化はしないでください。秘密のリカバリーフレーズや秘密鍵の入力は不要です。</p>
            {lastError && <pre style={{ whiteSpace: "pre-wrap", overflowWrap: "anywhere", maxWidth: "100%", fontSize: 13 }}>{JSON.stringify(diagnostic, null, 2)}</pre>}
            <a href="https://support.metamask.io/configure/networks/how-to-add-a-custom-network-rpc" target="_blank" rel="noopener noreferrer">MetaMask 公式のRPC設定手順</a>
        </details>
    </section>;
}
